class PlayerRating {
private:
    std::map<std::string, std::pair<int, int>> ratings;

public:
    void addWin(const std::string& playerName) {
        ratings[playerName].first += 1;
    }

    void addLoss(const std::string& playerName) {
        ratings[playerName].second += 1;
    }

    void saveToFile(const std::string& filename) const {
        std::ofstream file(filename);
        for (const auto& [name, stats] : ratings) {
            file << name << ',' << stats.first << ',' << stats.second << '\n';
        }
    }

    void loadFromFile(const std::string& filename) {
        std::ifstream file(filename);
        std::string line;
        while (std::getline(file, line)) {
            size_t pos1 = line.find(','), pos2 = line.find(',', pos1 + 1);
            std::string name = line.substr(0, pos1);
            int wins = std::stoi(line.substr(pos1 + 1, pos2 - pos1 - 1));
            int losses = std::stoi(line.substr(pos2 + 1));
            ratings[name] = {wins, losses};
        }
    }

    void displayRatings(sf::RenderWindow& window) const {
        sf::Font font;
        font.loadFromFile("arial.ttf");

        sf::Text text;
        text.setFont(font);
        text.setCharacterSize(24);
        text.setFillColor(sf::Color::White);

        int yPosition = 50;
        for (const auto& [name, stats] : ratings) {
            std::string textContent = name + ": Wins: " + std::to_string(stats.first) + ", Losses: " + std::to_string(stats.second);
            text.setString(textContent);
            text.setPosition(50, yPosition);
            window.draw(text);
            yPosition += 30;
        }
    }
};

