<script>
export default {
  data() {
    return {
      activeTab: null,
      selected: {},
      avatarUrl: '',
      categories: ['topType', 'accessoriesType', 'hairColor'],
      avatarOptions: {
        topType: [{ value: 'NoHair' }, { value: 'Eyepatch' }],
        accessoriesType: [{ value: 'Blank' }, { value: 'Kurt' }],
        hairColor: [{ value: 'Auburn' }, { value: 'Black' }]
      }
    };
  },
  methods: {
    computeOptionUrl(category, value) {
      let url = 'https://avataaars.io/?';
      for (let key in this.selected) {
        if (this.selected[key] !== undefined) {
          url += `${key}=${this.selected[key]}&`;
        }
      }
      url += `${category}=${value}`;
      return url;
    },
    updateAvatarUrl(category, value) {
      this.selected[category] = value;
      this.avatarUrl = this.computeOptionUrl();
    },
    saveToLocalStorage() {
      localStorage.setItem('avatarSelected', JSON.stringify(this.selected));
    },
    loadFromLocalStorage() {
      const savedData = JSON.parse(localStorage.getItem('avatarSelected'));
      if (savedData) {
        this.selected = savedData;
        this.updateAvatarUrl();
      }
    },
    getRows(category) {
      const options = this.avatarOptions[category];
      const rows = [];
      for (let i = 0; i < options.length; i += 3) {
        rows.push(options.slice(i, i + 3));
      }
      return rows;
    }
  },
  watch: {
    selected: {
      handler: 'saveToLocalStorage',
      deep: true
    }
  },
  mounted() {
    this.loadFromLocalStorage();
  }
};
</script>
