    Neuron n1;
    Neuron n2;

    n1.connect(&n2, 1.0); // Connect n1 to n2 with an initial weight

    for (int i = 0; i < 1000; ++i) {
        n1.step(10); // Apply constant current
        n1.updateSynapses(0.1); // Update synapses every time step
    }

    std::cout << "Final voltage of n2: " << n2.getVoltage() << std::endl;

    return 0;
}
